import sys

s = sys.stdin.read().split()[0]
n = len(s)
found = set()
for i in range(n):
    for j in range(i + 1, n + 1):
        t = s[i:j]
        ok = True
        for k in range(len(t) // 2):
            if t[k] != t[len(t) - 1 - k]:
                ok = False
                break
        if ok:
            found.add(t)
print(' '.join(sorted(found)))

